import SwiftUI

/// The wizard's four fixed steps (issue #151).
///
/// ```
///                     ┌─────────┐   Next    ┌──────┐   Next    ┌─────────────┐
///         launch ───► │ welcome │ ────────► │ tour │ ────────► │ addProject  │
///      (gate check)   └─────────┘           └──────┘           └─────────────┘
///                          ▲                    │ Back              │      │
///                          └────────────────────┘                   │      │ Skip
///                                                           success │      │
///                                                      (sets flag)  ▼      ▼
///                                                                 ┌──────────┐
///                                                                 │   done   │──► flag set
///                                                                 └──────────┘    (.onChange)
///                                                                      │
///                                                                 Get Started
