private func readHasCompletedOnboardingDefault() -> String {
  let read = Process()
  read.executableURL = URL(fileURLWithPath: "/usr/bin/defaults")
  read.arguments = ["read", bundleID, "onboarding.hasCompleted"]
  let pipe = Pipe()
  read.standardOutput = pipe
  read.standardError = pipe
  try? read.run()
  read.waitUntilExit()
  let data = pipe.fileHandleForReading.readDataToEndOfFile()
  return String(data: data, encoding: .utf8) ?? "<unreadable>"
}

