    return "could not read \(configURL.path)"
  }
  guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
    return "could not parse JSON at \(configURL.path)"
  }
  let marker = URL(fileURLWithPath: projectPath).lastPathComponent
  let matches = json.keys.filter { $0.hasSuffix(marker) }
  return "HOME=\(home) configURL=\(configURL.path) marker=\(marker) matches=\(matches) totalKeys=\(json.keys.count)"
}

/// Removes a single project entry from the real `~/.config/workroom/config.json` by path — the
/// only cleanup available since the bundled CLI has no config-path override to isolate against
/// instead (see the doc comment on `testAddingARealProjectAdvancesToDone`). Edits the JSON directly
/// rather than shelling out to `workroom delete-project`, to avoid depending on locating the bundled
/// binary inside the built app from a UI test. Best-effort: swallows errors rather than failing an
/// otherwise-passing test over cleanup of a file this test doesn't own.
private func removeFromRealCLIConfig(projectPath: String) {
  // NOT `FileManager.default.homeDirectoryForCurrentUser` — the UI test runner process appears to
  // be sandboxed/containerized (its own `temporaryDirectory` resolves under
  // `~/Library/Containers/com.developwithstyle.workroom.uitests.xctrunner/...`), so that API
  // likely resolves to a per-container home, not the real one the APP UNDER TEST (unsandboxed)
  // reads/writes. `$HOME` from the process environment is the one confirmed-real path (matches
  // what the app spawns its CLI subprocess with).
  guard let home = ProcessInfo.processInfo.environment["HOME"] else { return }
  let configURL = URL(fileURLWithPath: home).appendingPathComponent(".config/workroom/config.json")
  guard let data = try? Data(contentsOf: configURL),
    var json = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
  else { return }
  // Match by the distinctive last path component, not full-path equality: the CLI's own
  // canonicalization (Go-side, likely resolving symlinks) can register a different literal string
  // than this (sandboxed) test process's own unresolved path — but the generated directory NAME
  // (with its embedded UUID) survives that unchanged either way.
  let marker = URL(fileURLWithPath: projectPath).lastPathComponent
  let matches = json.keys.filter { $0.hasSuffix(marker) }
  guard !matches.isEmpty else { return }
  for key in matches { json.removeValue(forKey: key) }
  try? JSONSerialization.data(withJSONObject: json, options: [.prettyPrinted]).write(to: configURL)
}

