import Foundation

/// Shared, app-wide project data: the project list plus everything derived from it that is
/// identical across windows — root branch/bookmark labels, the VCS/CI status cache, GitHub-CLI
/// availability, and the in-flight project busy set. Extracted from `AppStore` (issue #70) so that
/// multiple per-window `AppStore`s can share one project list while each keeps its own selection,
/// terminals, splits, history, and run state.
///
/// This first step is **storage-only and behaviour-preserving**: `AppStore` proxies these
/// properties straight through to here and re-publishes the store's `objectWillChange`, so the
/// single shared `AppStore` still behaves exactly as before. The CLI/load logic stays on `AppStore`
/// for now (it mutates these via the proxies); per-window construction and the multi-window wiring
/// land in a follow-up.
@MainActor
final class ProjectStore: ObservableObject {
  /// The shared instance used in production (every window's `AppStore` points at it). Tests
  /// construct an isolated `AppStore()`, which gets its own fresh `ProjectStore`, so they never
  /// pollute this singleton or each other.
  static let shared = ProjectStore()

  /// The list of configured projects (from the CLI's `~/.config/workroom/config.json`). The one
  /// piece of state shared across all windows.
  @Published var projects: [Project] = []

  /// Per-project resolved root branch/bookmark labels, hydrated asynchronously after each load.
  @Published var rootRefs: [Project.ID: RootRef] = [:]

  /// Per-workroom (and per-root) VCS + CI status driving the ambient badges and the Changes panel
  /// (issue #24), keyed by `SidebarID`. Resolved app-side, best-effort/"last checked". Shared so two
  /// windows showing the same workroom report a consistent badge and don't double the probes.
  @Published var workroomStatuses: [SidebarID: WorkroomStatus] = [:]

  /// Whether the GitHub CLI is usable for the PR/CI probes (machine-global). Optimistic default so
  /// no warning flashes before the first check.
  @Published var githubCLIStatus: GitHubCLIStatus = .available

  /// Owns the `gh auth status` probe: its freshness clock AND its single-flight, so N windows share
  /// one `gh` and the staleness check can't interleave with the write the way a bare timestamp on
  /// this class did. `githubCLIStatus` above is the SwiftUI-observable mirror of what it decided.
  ///

import AppKit
import Defaults
import SwiftUI

/// The single app-level coordinator for the multi-window world (issue #70). Each window owns its own
/// `AppStore` (per-window selection, terminals, splits, run state); this registry is the *only*
/// shared coordination point above them, for the things that are genuinely app-scoped:
///
/// - **Key/active routing** — the `AppDelegate` key-event monitor and a terminal surface's
///   context-menu actions act on whichever window is key (`keyStore`).
/// - **Last-active capture** — `lastActiveStore` tracks the most recent *workroom* window to become
///   key, captured before any modal (quit alert / Settings) can steal key status, so quit-time
///   persistence reads the right window.
/// - **Aggregation** — the Dock badge (and menu-bar item) sum across every window's notifications.
/// - **Run-command ownership** — a workroom's run command is single-owner across windows; a second
///   window's Run focuses the owner instead of forking a duplicate server (issue #70 / issue #7).
/// - **Quit/close de-dup** — `isTerminating` suppresses the per-window close prompt during a quit.
///
/// Per-window logic stays in `AppStore`; this holds only weak references, so closed windows fall out
/// on the next prune.
@MainActor
final class WindowRegistry: ObservableObject {
  static let shared = WindowRegistry()

  private final class Entry {
    weak var window: NSWindow?
    weak var store: AppStore?
    init(window: NSWindow, store: AppStore) {
      self.window = window
      self.store = store
    }
  }
  private var entries: [Entry] = []

  /// True while the app is terminating, so a window's close handler doesn't prompt/stop run commands
  /// a second time on top of `applicationShouldTerminate` (issue #70, OV #10).
  var isTerminating = false

  /// The most recent registered (workroom) window to become key. Updated only for registered windows,
  /// so a modal alert / Settings becoming key never overwrites it — quit persistence can trust it.
  private(set) weak var lastActiveStore: AppStore?

  /// Combined unread notification count across every window — drives the menu-bar label + Dock badge
  /// (issue #70). `@Published` so the `MenuBarExtra` label re-renders as any window's count changes.
  @Published private(set) var aggregateUnread = 0

  init() {
    // Track the active workroom window. Only registered windows update `lastActiveStore`, so the quit
    // alert / Settings / menu-bar popover becoming key leaves the last *workroom* selection intact.
    NotificationCenter.default.addObserver(
      forName: NSWindow.didBecomeKeyNotification, object: nil, queue: .main
    ) { [weak self] note in
      MainActor.assumeIsolated {
        guard let self, let window = note.object as? NSWindow,
          let store = self.store(for: window)
        else { return }
        self.lastActiveStore = store
        // Which window was key is part of the saved session — it decides where the user lands after
        // a restore (issue #46).
        SessionCoordinator.shared.markDirty()
        // Bringing a window forward makes its selection the most recent one (issue #132). Without
        // this, ⌘` to another window leaves the switcher's MRU head pointing at the window you left,
        // so the next ⌥Tab tap flips somewhere you didn't come from.
        SwitcherRecency.shared.recordWorkroom(store: store, sid: store.selectedTargetID)
      }
    }
    // Drop a window as it closes (issue #46). `unregister` previously had NO caller: entries were
    // only ever cleared by `prune()` noticing the weak reference had died, which happens whenever the
    // next unrelated lookup runs — so a closed window scheduled no save, and the session file kept
    // describing it until something else happened to mark the session dirty. Filtered to registered
    // workroom windows, so Settings/About/quick terminal closing here is a no-op.
    NotificationCenter.default.addObserver(
      forName: NSWindow.willCloseNotification, object: nil, queue: .main
    ) { [weak self] note in
      MainActor.assumeIsolated {
        guard let self, let window = note.object as? NSWindow, self.store(for: window) != nil
        else { return }
        self.unregister(window: window)
      }
    }
  }

  // MARK: Registration

  /// Register (or re-register) a window with its store. Idempotent — `WindowAccessor` may resolve the
  /// same window more than once. Prunes any dead entries while here.
  func register(window: NSWindow, store: AppStore) {
    prune()
    if let existing = entries.first(where: { $0.window === window }) {
      existing.store = store
    } else {
      entries.append(Entry(window: window, store: store))
    }
    assignWindowNumberIfNeeded(store)
    if lastActiveStore == nil { lastActiveStore = store }
    recomputeBadge()
    // The saved session is rebuilt from the live windows (issue #46), and the window layer publishes
    // through none of the store's own publishers — so opening a window has to say so itself.
    SessionCoordinator.shared.markDirty()
  }

  /// Whether this window may adopt a saved session — true for the launch window and for each sibling
  /// it reopens (issue #46), false for every ⌘N window, which always starts blank.
  let restore: Bool
  /// Whether this is THE launch window, as opposed to a sibling reopened from the saved session.
  ///
  /// Separate from `restore` because the two answer different questions and both siblings and the
  /// launch window restore. Only the launch window runs the What's-New auto-check and fans the
  /// siblings out — without this distinction every restored window would pop that dialog.
  var isLaunch = false

  /// The launch window: a fresh id allowed to restore the saved session.
  static var launch: WindowSeed { WindowSeed(id: UUID(), restore: true, isLaunch: true) }

  /// A window reopened from the saved session, keyed on the session it will claim.
  static func restoring(key: UUID) -> WindowSeed {
    WindowSeed(id: key, restore: true, isLaunch: false)
  }
}

/// One window's root. The value-based `WindowGroup` gives each window its own `RootWindow`, so the
/// `@StateObject` below is a fresh per-window `AppStore` sharing the one `ProjectStore`. It injects
/// that store into the environment, exposes it to menu commands via `focusedSceneObject`, and
/// registers the window↔store pair with `WindowRegistry` (issue #70).
struct RootWindow: View {
  let seed: WindowSeed
  @StateObject private var store: AppStore
  @Environment(\.openWindow) private var openWindow

  init(seed: WindowSeed) {
    self.seed = seed
    let store = AppStore(projectStore: .shared)
    // Capture the current window's size ONCE, at this window's creation, so the new window can be
    // sized to match it before it's shown (issue #70). nil for the launch window.
    store.pendingInitialWindowSize = WindowRegistry.shared.preferredNewWindowSize
    // Only the launch window runs the What's-New auto-check (see RootView). Sibling windows reopened
    // from the saved session also carry `restore: true`, so gating on that would pop the dialog once
    // per restored window (issue #46).
    store.isRestoreWindow = seed.isLaunch
    // Which saved window this one adopts. The launch window takes the first unclaimed session; a
    // sibling was opened FOR a specific key and claims exactly that one.
    store.sessionKey = seed.id
    store.claimsSavedSession = seed.restore
    _store = StateObject(wrappedValue: store)
  }

  var body: some View {
    RootView()
      .environmentObject(store)
      .environmentObject(store.notifications)
      .environmentObject(store.terminals)
      .environmentObject(store.terminals.agentManager)
      .focusedSceneObject(store)
      .frame(minWidth: 900, maxWidth: .infinity, minHeight: 560, maxHeight: .infinity)
      .background(
        WindowAccessor { window in
          WindowRegistry.shared.register(window: window, store: store)
          store.attachWindow(window)
        }
      )
      .task {
        // Not under XCTest: `WorkroomAppTests` hosts this app to get `@testable import Workroom`,
        // which means this real WindowGroup scene renders too — and without this guard, its `.task`
        // ran on every `make app-test`, unconditionally `bootstrap()`ing the SHARED, non-fake
        // `AppStore` (production default `cli: WorkroomCLI.shared`) against the developer's REAL
        // `~/.config/workroom/config.json`, then opening a REAL terminal in a REAL project
        // directory for whatever it found. Same guard, same reasoning, as the `ShellEnvironment`
        // skip in `init` above. Unit tests construct their own isolated `AppStore()`s and never see
        // this window at all, so skipping its bootstrap breaks nothing under test.
        guard ProcessInfo.processInfo.environment["XCTestConfigurationFilePath"] == nil else {
          return
        }
        await store.bootstrap(restore: seed.restore)
        // First-run onboarding (issue #151) — only the launch window ever reaches this line (see
        // `shouldOpenOnboarding`), so it can't be reconsidered on a ⌘N window. `openWindow(id:)` on a
        // `Window` scene is idempotent, so a `.task` re-fire can't double-open it either.
        if Self.shouldOpenOnboarding(
          seed: seed, hasCompleted: Defaults[.hasCompletedOnboarding],
          projectsEmpty: store.projects.isEmpty
        ) {
          openWindow(id: OnboardingWindow.sceneID)
        }
        // Reopen the windows that were open at the last quit (issue #46). Only the launch window
        // fans out, and each key is handed out once, so a `.task` re-fire cannot double-open.
        guard seed.isLaunch else { return }
        for key in ProjectStore.shared.pendingSessionKeys() {

