    // to find this specific window among any others open.
    window.setAccessibilityIdentifier("onboarding.window")
    // The launch window hides itself behind this one (`RootWindow`'s `WindowAccessor`) whenever
    // onboarding might be needed, so it has to be brought forward again once this window closes —
    // by ANY path (Get Started, ⌘W, the red button): the user asked for the main window to open
    // only once the wizard is closed or finished, not underneath it the whole time. One-shot: this
    // window only ever closes once, so the observer removes itself right after firing.
    var token: NSObjectProtocol?
    token = NotificationCenter.default.addObserver(
      forName: NSWindow.willCloseNotification, object: window, queue: .main
    ) { _ in
      MainActor.assumeIsolated {
        WindowRegistry.shared.lastActiveStore?.hostWindow?.makeKeyAndOrderFront(nil)
      }
      if let token { NotificationCenter.default.removeObserver(token) }
    }
  }
)

