@Published var inspectorSizeWeights: [Double] = [1, 1, 1, 1]
/// The selected top-level section in the right activity bar (issue: activity bar). Drives which
/// pane the inspector shows (`RightInspector` renders `activeInspectorSection.subSections`). Held
/// as `@Published` (not read via `@Default` in the bar) so a click re-renders the bar + inspector
/// synchronously — a bare `@Default` write invalidates asynchronously (the `SettingsView` gotcha).
/// Persisted per-machine via `didSet`; whether the pane is visible at all is `Defaults[.showInspector]`.
@Published var activeInspectorSection: ActivitySection = Defaults[.activeInspectorSection] {
  didSet {
    if activeInspectorSection != oldValue {
      if !isolatesInspectorSectionForTesting {
        Defaults[.activeInspectorSection] = activeInspectorSection
      }
      // Switching to a pane that stacks History, with a workroom already selected: point the model
      // now so the pane shows its loader immediately, instead of flashing the `.idle` ("Select a
      // workroom") placeholder until the panel's `.task` catches up. `focus` is idempotent (no-op if
      // already there).
      focusHistoryIfShown()
      focusRemoteStateIfShown()
    }
  }
}
/// Test seam: keep collapse/size changes in THIS store instead of persisting them to the shared
/// `inspector.layout.v2` setting — the third half of the gate `inspectorVisibleOverrideForTesting`
/// and `isolatesInspectorSectionForTesting` cover, and the same cross-worker hazard: a class that
/// needs History expanded (or collapsed) would otherwise leave that value inside whatever unrelated
/// class runs beside it, since `-parallel-testing` workers share one UserDefaults domain.
var isolatesInspectorLayoutForTesting = false
/// Test seam: keep an `activeInspectorSection` change in THIS store instead of persisting it to the
/// shared `inspector.activeSection` setting. Same hazard as `confirmOnCloseOverrideForTesting`
/// (which see for the full account): `-parallel-testing` gives each worker its own host process but
/// ONE UserDefaults domain, so a class that wants its store on History leaves every store another
/// worker builds meanwhile starting on History too — and the `selectedTargetID` didSet then focuses
/// `commitHistory` (a real VCS read on a fixture path) in a test that never asked for History.
var isolatesInspectorSectionForTesting = false
/// Test seam: pin whether the inspector pane counts as visible, per store, instead of writing the
/// shared `showInspector` setting. `nil` (production) reads the real setting.
///
/// The live-History triggers gate on the pane being *visible*, so the tests that drive them have to
/// control it — and writing the key to do that is the same cross-worker leak as above, one key over.
/// Those windows were short enough never to have gone red, which is not the same as being safe.
var inspectorVisibleOverrideForTesting: Bool?
/// Whether the inspector pane is open: a test's pinned value if there is one, else the setting.
var inspectorIsVisible: Bool {
  Self.resolveInspectorVisible(override: inspectorVisibleOverrideForTesting)
}
/// The override-or-setting half of `inspectorIsVisible`, lifted out as a pure static for the same
/// reason `resolveConfirmOnClose` is one: once the History classes inject the override, no test
/// reaches the `Defaults` side, so hard-coding this `true` would leave the suite green while the
/// live-History refresh quietly started reading VCS behind a closed pane. `nonisolated` because it
/// touches no actor state — just its argument and a `Defaults` read.
nonisolated static func resolveInspectorVisible(override: Bool?) -> Bool {
  override ?? Defaults[.showInspector]
}
/// The repo file tree behind the inspector's Files section. Re-pointed at the selected target's
/// directory whenever the selection changes (see `selectedTargetID.didSet`); the `FilesPanel`

/// The two-column `NavigationSplitView` core (sidebar + detail/inspector). The window chrome, modal
/// presentations, and lifecycle hooks layer on in `body` via the `root*` helpers below — each its own
/// function so the modifier chain type-checks within the compiler's budget. The fully-inline chain
/// timed out the type-checker on CI ("unable to type-check this expression in reasonable time"); this
/// is the same split-it-up reason `EdgeRevealSidebars`/`MenuStateValues`/`NewWorkroomPresenter` exist.
private var splitView: some View {
  // A hand-rolled split (sidebar | detail | inspector) instead of `NavigationSplitView`: the native
  // sidebar column drew an inset card with a ~30pt top toolbar-reserve that left an empty gap under
  // the custom title bar, and that inset isn't controllable. `SidebarColumn`/`InspectorColumn` are
  // our own resizable cards (same `sidebarCard` as the edge-reveal, so pinned == unpinned), giving
  // full control over their position. Visibility round-trips through `store.sidebarVisible` /
  // `showInspector` (the View-menu ticks + toggles); width persists per column to `Defaults`.
  // A *detail-only* NavigationSplitView: we keep it (vs a plain HStack) only for the window
  // toolbar/layering context it sets up — that's what lets the custom title bar, drawn in the
  // full-size content under the native title bar, render crisp instead of washed-out by the
  // title-bar vibrancy (a plain HStack / NavigationStack doesn't). Its native sidebar column is
  // never used (forced `.detailOnly`) — that column is what kept the ~30pt inset-card top gap — so
  // the real sidebar is our own `SidebarColumn` in the detail HStack, flush below the bar.
  // Wrapped in a *detail-only* `NavigationSplitView` (empty sidebar column, forced `.detailOnly`) —
  // NOT a plain HStack. A plain HStack detail in a full-size-content window with a visible `.unified`
  // toolbar loses SwiftUI `.onHover` for its content that sits near the top under the title bar (the
  // terminal tab strip's trailing toolbar buttons never lit their hover well — issue #114); the
  // title-bar region eats mouse-moved for a raw content view. `NavigationSplitView` hosts the detail
  // in an `NSSplitViewController`, which sets up the correct content tracking so `.onHover` fires
  // again. Dropping it (0e354d6e) was to stop it clipping `.toolbar { items }` to the sidebar-column
  // width — but the chrome no longer lives in toolbar items; it's a full-width window-level `.left`
  // `TitlebarAccessoryHost` (see `accessoryBarContent`), which NavigationSplitView does not clip. So
  // we get correct hover back with no clipping. The empty native sidebar column is unused — the real
  // sidebar is our own `SidebarColumn` in the detail HStack, flush below the bar.
  NavigationSplitView(columnVisibility: .constant(.detailOnly)) {
    Color.clear.frame(width: 0)
  } detail: {
    HStack(spacing: 0) {
      if store.sidebarVisible {
        SidebarColumn(
          paneDrag: $workroomChipDrag,
          localize: { workroomChipLocal($0) },
          dropTarget: { workroomChipDropTarget(at: $0) }
        )
        .transition(.move(edge: .leading))
      }
      detail
        .frame(maxWidth: .infinity, maxHeight: .infinity)
      if showInspector {
        InspectorColumn()
          .transition(.move(edge: .trailing))
      }
      // The activity bar is ALWAYS present, flush to the window's trailing edge — the inspector
      // content pane (above) slides in/out beside it. Placed inside the detail-only
      // NavigationSplitView so its icon buttons get working `.onHover` (issue #114).
      ActivityBar()
    }
    .animation(reduceMotion ? nil : .easeInOut(duration: 0.2), value: store.sidebarVisible)
    .animation(reduceMotion ? nil : .easeInOut(duration: 0.2), value: showInspector)
  }
}

