### `/Users/joelmoss/dev/workroom/macapp/Scripts/make-icon.swift`
- Added a new `AppMark.imageset` generation block (128px/256px), using the SAME `renderMenuBarGlyph` function as `MenuBarIcon` (just called at different pixel sizes) — added after user reported "the logo on that screen is bad quality":
```swift
// Same template glyph, rendered at 128pt instead of 18pt — for large in-content uses...
do {
    let dir = URL(fileURLWithPath: assetsDir, isDirectory: true)
        .appendingPathComponent("AppMark.imageset", isDirectory: true)
    try! FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
    let glyphOutputs: [(String, Int)] = [("mark_128.png", 128), ("mark_128@2x.png", 256)]
    for (name, px) in glyphOutputs {
        renderMenuBarGlyph(px, to: dir.appendingPathComponent(name))
    }
    let glyphContents = """
        {
          "images" : [
            { "idiom" : "universal", "scale" : "1x", "filename" : "mark_128.png" },
            { "idiom" : "universal", "scale" : "2x", "filename" : "mark_128@2x.png" }
          ],
          "info" : { "author" : "xcode", "version" : 1 },
          "properties" : { "template-rendering-intent" : "template" }
        }
        """
    try! glyphContents.write(to: dir.appendingPathComponent("Contents.json"), atomically: false, encoding: .utf8)
}
